    ],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const totalsResult = invoiceTotals(invoice);

  assert.equal(totalsResult.ok, true);
  const expected = (8 * 9500) + (5 * 8500);
  assert.equal(totalsResult.value.subtotal, expected);
  assert.equal(totalsResult.value.total, expected);
});

